import sys

def solve():
    # Read N
    try:
        line1 = sys.stdin.readline()
        if not line1:
            return
        n = int(line1.strip())

        # Read S and T
        s = sys.stdin.readline().strip()
        t = sys.stdin.readline().strip()

        # Calculate Hamming distance
        diff_count = 0
        for i in range(n):
            if s[i] != t[i]:
                diff_count += 1

        print(diff_count)
    except ValueError:
        pass

if __name__ == "__main__":
    solve()
