class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n = len(s)
        m = len(t)
        max_len = 0

        # Iterate over all substrings of s
        for i in range(n):
            for j in range(i, n):
                sub_s = s[i:j+1]
                # Iterate over all substrings of t
                for k in range(m):
                    for l in range(k, m):
                        sub_t = t[k:l+1]
                        concat = sub_s + sub_t
                        if is_palindrome(concat):
                            max_len = max(max_len, len(concat))
        return max_len

def is_palindrome(s):
    return s == s[::-1]
